#include "NeuralSignalQualityGate.h"
namespace dnxr { NeuralSignalGateDecision NeuralSignalQualityGate::evaluate(float q,bool drop,float art,int rep) const { if(drop) return {NeuralSignalGateAction::HoldLastSafeFrame,false,false,"packet_dropout"}; if(q<0.25f) return {NeuralSignalGateAction::BlockStimulus,false,false,"critical_signal_quality"}; if(art>0.7f) return {rep>2?NeuralSignalGateAction::Recalibration:NeuralSignalGateAction::RealityAnchor,false,false,"artifact_high"}; if(q<0.55f) return {NeuralSignalGateAction::BlockIntent,false,true,"low_signal_quality_blocks_intent"}; return {NeuralSignalGateAction::AllowIntentAndStimulus,true,true,"signal_quality_ok"}; } }
